@Composable
private fun HomeScreen(
    transactions: List<TransactionEntity>,
    onTransaction: (String) -> Unit,
    onPending: () -> Unit,
    onEnablePermissions: () -> Unit,
    modifier: Modifier = Modifier,
) {
    val context = LocalContext.current
    val lifecycleOwner = LocalLifecycleOwner.current
    var permissionRefresh by remember { mutableIntStateOf(0) }
    DisposableEffect(lifecycleOwner) {
        val observer = LifecycleEventObserver { _, event -> if (event == Lifecycle.Event.ON_RESUME) permissionRefresh++ }
        lifecycleOwner.lifecycle.addObserver(observer)
        onDispose { lifecycleOwner.lifecycle.removeObserver(observer) }
    }
    @Suppress("UNUSED_VARIABLE") val refresh = permissionRefresh
    val smsGranted = ContextCompat.checkSelfPermission(context, Manifest.permission.RECEIVE_SMS) == PackageManager.PERMISSION_GRANTED
    val notificationGranted = Build.VERSION.SDK_INT < 33 || ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED
    val zone = ZoneId.systemDefault()
    val today = LocalDate.now(zone)
    val todayItems = transactions.filter { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() == today }
    val (moneyIn, moneyOut) = todayItems.includedTotals()
    val refunds = todayItems.filter { it.kind == TransactionKind.REFUND || it.kind == TransactionKind.REVERSAL }.sumOf { it.amountMinor }
    val spent = moneyOut - refunds
    val pending = transactions.count { it.direction == Direction.DEBIT && it.title.isNullOrBlank() }

    LazyColumn(
        modifier.fillMaxSize().statusBarsPadding(),
        contentPadding = PaddingValues(20.dp, 18.dp, 20.dp, 32.dp),
        verticalArrangement = Arrangement.spacedBy(16.dp),
    ) {
        item {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Column(Modifier.weight(1f)) {
                    Text("Penny", style = MaterialTheme.typography.headlineLarge)
                    Text(today.format(DateTimeFormatter.ofPattern("EEEE, d MMMM")), style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                }
                Surface(color = MaterialTheme.colorScheme.surface.copy(alpha = .74f), shape = CircleShape, modifier = Modifier.size(46.dp)) {
                    Icon(Icons.Outlined.AutoAwesome, "Penny is active", tint = MaterialTheme.colorScheme.primary, modifier = Modifier.padding(12.dp))
                }
            }
        }
        item { AuroraBalanceCard(spent, moneyIn, moneyOut) }
        if (!smsGranted) item { PermissionCard("SMS access is off", "New bank alerts cannot be captured.", "Enable", onEnablePermissions) }
        if (!notificationGranted) item { PermissionCard("Expense reminders are off", "Debits are still saved when SMS access is on.", "Enable", onEnablePermissions) }
        if (pending > 0) item {
            AnimatedVisibility(visible = true, enter = fadeIn() + scaleIn(initialScale = .97f)) {
                PendingExpenses(pending, onPending)
            }
        }
        item {
            Row(Modifier.padding(top = 8.dp), verticalAlignment = Alignment.CenterVertically) {
                Text("Today", style = MaterialTheme.typography.titleLarge, modifier = Modifier.weight(1f))
                Text("${todayItems.size} ${if (todayItems.size == 1) "movement" else "movements"}", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
            }
        }
        if (todayItems.isEmpty()) item { EmptyState("Your day starts here", "Transactions appear when a bank SMS arrives.") }
        else item {
            GlassPanel(contentPadding = PaddingValues(horizontal = 16.dp, vertical = 4.dp)) {
                todayItems.forEachIndexed { index, transaction ->
                    TransactionRow(transaction) { onTransaction(transaction.id) }
                    if (index != todayItems.lastIndex) HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = .45f))
                }
            }
        }
    }
}

@Composable
private fun AuroraBalanceCard(spent: Long, moneyIn: Long, moneyOut: Long) {
    var focus by rememberSaveable { mutableStateOf(BalanceFocus.SPENT) }
    val scale by animateFloatAsState(
        targetValue = if (focus == BalanceFocus.SPENT) 1f else 1.012f,
        animationSpec = spring(dampingRatio = .78f, stiffness = 220f),
        label = "balance lobe spring",
    )
    val focusedLabel = when (focus) {
        BalanceFocus.SPENT -> "Spent today"
        BalanceFocus.IN -> "Money in today"
        BalanceFocus.OUT -> "Money out today"
    }
    val focusedAmount = when (focus) {
        BalanceFocus.SPENT -> spent
        BalanceFocus.IN -> moneyIn
        BalanceFocus.OUT -> moneyOut
    }
    Box(
        Modifier
            .fillMaxWidth()
            .height(244.dp)
            .scale(scale)
            .shadow(24.dp, RoundedCornerShape(30.dp), ambientColor = AuroraViolet.copy(alpha = .30f), spotColor = AuroraMagenta.copy(alpha = .22f))
            .clip(RoundedCornerShape(topStart = 38.dp, topEnd = 24.dp, bottomEnd = 42.dp, bottomStart = 24.dp))
            .background(Brush.linearGradient(listOf(Color(0xFF4221B8), Color(0xFF6534C7), Color(0xFFA42D7E))))
            .drawBehind {
                drawCircle(Color.White.copy(alpha = .07f), size.width * .64f, Offset(size.width * .93f, size.height * .06f))
                drawCircle(AuroraCyan.copy(alpha = .11f), size.width * .42f, Offset(size.width * .18f, size.height * 1.02f))
            }
            .padding(24.dp),
    ) {
        Column(Modifier.fillMaxSize(), verticalArrangement = Arrangement.SpaceBetween) {
            Column {
                AnimatedContent(targetState = focusedLabel, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "balance label") { label ->
                    Text(label, style = MaterialTheme.typography.labelLarge, color = Color.White)
                }
                AnimatedContent(targetState = focusedAmount, transitionSpec = { fadeIn() togetherWith fadeOut() }, label = "balance amount") { amount ->
                    Text(formatMoney(amount), style = MaterialTheme.typography.displayMedium, color = Color.White)
                }
                Text("From captured bank alerts", style = MaterialTheme.typography.bodySmall, color = Color.White)
            }
            BalanceSelector(focus, spent, moneyIn, moneyOut) { focus = it }
        }
    }
}

@Composable
private fun BalanceSelector(
    focus: BalanceFocus,
    spent: Long,
    moneyIn: Long,
    moneyOut: Long,
    onFocus: (BalanceFocus) -> Unit,
) {
    val choices = listOf(
        Triple(BalanceFocus.SPENT, "Spent", spent),
        Triple(BalanceFocus.IN, "In", moneyIn),
        Triple(BalanceFocus.OUT, "Out", moneyOut),
    )
    BoxWithConstraints(
        Modifier.fillMaxWidth().height(78.dp).clip(RoundedCornerShape(20.dp)).background(Color.Black.copy(alpha = .14f)),
    ) {
        val segmentWidth = maxWidth / choices.size
        val position by animateDpAsState(
            targetValue = segmentWidth * choices.indexOfFirst { it.first == focus },
            animationSpec = spring(dampingRatio = .78f, stiffness = 240f),
            label = "traveling balance highlight",
        )
        Surface(
            modifier = Modifier.offset(x = position).width(segmentWidth).height(78.dp).padding(5.dp),
            color = Color.White.copy(alpha = .18f),
            shape = RoundedCornerShape(16.dp),
        ) { }
        Row(Modifier.fillMaxSize().selectableGroup()) {
            choices.forEach { (value, label, amount) ->
                Column(
                    Modifier.weight(1f).fillMaxSize().selectable(
                        selected = focus == value,
                        onClick = { onFocus(value) },
                        role = Role.RadioButton,
                    ).semantics { contentDescription = "$label ${formatMoney(amount)}" },
                    verticalArrangement = Arrangement.Center,
                    horizontalAlignment = Alignment.CenterHorizontally,
                ) {
                    Text(label, style = MaterialTheme.typography.labelMedium, color = Color.White)
                    Text(formatMoney(amount), style = MaterialTheme.typography.titleMedium, color = if (value == BalanceFocus.IN) Color(0xFFB7FFE5) else Color.White)
                }
            }
        }
    }
}

