@OptIn(ExperimentalMaterial3Api::class)
@Composable
private fun HistoryScreen(transactions: List<TransactionEntity>, onTransaction: (String) -> Unit, modifier: Modifier = Modifier) {
    var filter by rememberSaveable { mutableStateOf(HistoryFilter.WEEK) }
    var chosenDateEpochDay by rememberSaveable { mutableStateOf<Long?>(null) }
    var showDatePicker by remember { mutableStateOf(false) }
    val zone = ZoneId.systemDefault()
    val today = LocalDate.now(zone)
    val chosenDate = chosenDateEpochDay?.let(LocalDate::ofEpochDay) ?: today
    val from = when (filter) { HistoryFilter.TODAY -> today; HistoryFilter.YESTERDAY -> today.minusDays(1); HistoryFilter.WEEK -> today.minusDays(6); HistoryFilter.CHOOSE -> chosenDate }
    val to = when (filter) { HistoryFilter.YESTERDAY -> today.minusDays(1); HistoryFilter.CHOOSE -> chosenDate; else -> today }
    val filtered = transactions.filter { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() in from..to }
    val (moneyIn, moneyOut) = filtered.includedTotals()

    LazyColumn(
        modifier.fillMaxSize().statusBarsPadding(),
        contentPadding = PaddingValues(20.dp, 18.dp, 20.dp, 32.dp),
        verticalArrangement = Arrangement.spacedBy(14.dp),
    ) {
        item {
            Text("History", style = MaterialTheme.typography.headlineLarge)
            Text("Every captured movement, in order.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
        }
        item {
            LazyRow(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                HistoryFilter.entries.forEach { value ->
                    item(value) {
                        FilterChip(
                            selected = filter == value,
                            onClick = { if (value == HistoryFilter.CHOOSE) showDatePicker = true else filter = value },
                            label = { Text(when (value) { HistoryFilter.TODAY -> "Today"; HistoryFilter.YESTERDAY -> "Yesterday"; HistoryFilter.WEEK -> "Last 7 days"; HistoryFilter.CHOOSE -> "Choose date" }) },
                        )
                    }
                }
            }
        }
        item {
            GlassPanel {
                Text(
                    if (from == to) from.format(DateTimeFormatter.ofPattern("d MMMM uuuu")) else "${from.format(DateTimeFormatter.ofPattern("d MMM"))} – ${to.format(DateTimeFormatter.ofPattern("d MMM uuuu"))}",
                    style = MaterialTheme.typography.labelLarge,
                    color = MaterialTheme.colorScheme.onSurfaceVariant,
                )
                Spacer(Modifier.height(14.dp))
                Row {
                    HistoryTotal("Money in", moneyIn, true, Modifier.weight(1f))
                    HistoryTotal("Money out", moneyOut, false, Modifier.weight(1f))
                }
            }
        }
        if (filtered.isEmpty()) item { EmptyState("Nothing in this period", "Try another date range.") }
        else {
            val groups = filtered.groupBy { Instant.ofEpochMilli(it.occurredAt).atZone(zone).toLocalDate() }.toSortedMap(reverseOrder())
            groups.forEach { (date, values) ->
                item { Text(if (date == today) "Today" else date.format(DateTimeFormatter.ofPattern("EEEE, d MMMM")), style = MaterialTheme.typography.titleMedium, modifier = Modifier.padding(top = 10.dp)) }
                item {
                    GlassPanel(contentPadding = PaddingValues(horizontal = 16.dp, vertical = 4.dp)) {
                        values.forEachIndexed { index, transaction ->
                            TransactionRow(transaction) { onTransaction(transaction.id) }
                            if (index != values.lastIndex) HorizontalDivider(color = MaterialTheme.colorScheme.outlineVariant.copy(alpha = .45f))
                        }
                    }
                }
            }
        }
    }
    if (showDatePicker) {
        val pickerState = rememberDatePickerState(
            initialSelectedDateMillis = chosenDate.atStartOfDay(ZoneOffset.UTC).toInstant().toEpochMilli(),
            selectableDates = object : SelectableDates {
                override fun isSelectableDate(utcTimeMillis: Long): Boolean = Instant.ofEpochMilli(utcTimeMillis).atZone(ZoneOffset.UTC).toLocalDate() <= today
            },
        )
        DatePickerDialog(
            onDismissRequest = { showDatePicker = false },
            confirmButton = { TextButton(onClick = {
                pickerState.selectedDateMillis?.let {
                    chosenDateEpochDay = Instant.ofEpochMilli(it).atZone(ZoneOffset.UTC).toLocalDate().toEpochDay()
                    filter = HistoryFilter.CHOOSE
                }
                showDatePicker = false
            }) { Text("Choose") } },
            dismissButton = { TextButton(onClick = { showDatePicker = false }) { Text("Cancel") } },
        ) { DatePicker(pickerState) }
    }
}

