    val label = when {
        transaction.kind == TransactionKind.REFUND -> "Refund · ${transaction.title ?: transaction.merchantOrSender ?: "Purchase"}"
        transaction.kind == TransactionKind.OWN_TRANSFER -> "Transfer"
