        !transaction.title.isNullOrBlank() -> transaction.title
        else -> "Add a title"
    }
    Row(
        Modifier.fillMaxWidth().clickable(onClick = onClick).padding(vertical = 14.dp),
        verticalAlignment = Alignment.CenterVertically,
    ) {
