@Composable
private fun SettingsScreen(
    themeMode: PennyThemeMode,
    notificationsEnabled: Boolean,
    notificationSoundEnabled: Boolean,
    onThemeMode: (PennyThemeMode) -> Unit,
    onNotifications: (Boolean) -> Unit,
    onNotificationSound: (Boolean) -> Unit,
    onRequestPermissions: () -> Unit,
    onTestNotification: () -> Unit,
    onDelete: () -> Unit,
    onSimulateDebit: () -> Unit,
    onSimulateCredit: () -> Unit,
    modifier: Modifier = Modifier,
) {
    var page by rememberSaveable { mutableStateOf(SettingsPage.MAIN) }
    BackHandler(page != SettingsPage.MAIN) { page = SettingsPage.MAIN }
    AnimatedContent(
        targetState = page,
        transitionSpec = {
            val forward = targetState != SettingsPage.MAIN
            (fadeIn() + slideInHorizontally { if (forward) it / 3 else -it / 3 }).togetherWith(
                fadeOut() + slideOutHorizontally { if (forward) -it / 4 else it / 4 },
            )
        },
        label = "settings detail",
        modifier = modifier,
    ) { destination ->
        when (destination) {
            SettingsPage.MAIN -> SettingsMain(
                themeMode, notificationsEnabled, notificationSoundEnabled, onThemeMode,
                onNotifications, onNotificationSound, onRequestPermissions, onTestNotification,
                onPrivacy = { page = SettingsPage.PRIVACY },
                onAbout = { page = SettingsPage.ABOUT },
                onDelete, onSimulateDebit, onSimulateCredit,
            )
            SettingsPage.PRIVACY -> PrivacyScreen { page = SettingsPage.MAIN }
            SettingsPage.ABOUT -> AboutScreen { page = SettingsPage.MAIN }
        }
    }
}

@Composable
private fun SettingsMain(
    themeMode: PennyThemeMode,
    notificationsEnabled: Boolean,
    notificationSoundEnabled: Boolean,
    onThemeMode: (PennyThemeMode) -> Unit,
    onNotifications: (Boolean) -> Unit,
    onNotificationSound: (Boolean) -> Unit,
    onRequestPermissions: () -> Unit,
    onTestNotification: () -> Unit,
    onPrivacy: () -> Unit,
    onAbout: () -> Unit,
    onDelete: () -> Unit,
    onSimulateDebit: () -> Unit,
    onSimulateCredit: () -> Unit,
) {
    val context = LocalContext.current
    val smsGranted = ContextCompat.checkSelfPermission(context, Manifest.permission.RECEIVE_SMS) == PackageManager.PERMISSION_GRANTED
    val notificationGranted = Build.VERSION.SDK_INT < 33 || ContextCompat.checkSelfPermission(context, Manifest.permission.POST_NOTIFICATIONS) == PackageManager.PERMISSION_GRANTED
    var confirmDelete by remember { mutableStateOf(false) }
    LazyColumn(
        Modifier.fillMaxSize().statusBarsPadding(),
        contentPadding = PaddingValues(20.dp, 18.dp, 20.dp, 32.dp),
        verticalArrangement = Arrangement.spacedBy(18.dp),
    ) {
        item {
            Text("Settings", style = MaterialTheme.typography.headlineLarge)
            Text("Make Penny feel right on this phone.", style = MaterialTheme.typography.bodyMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
        }
        item {
            SettingsSection("Appearance") {
                SettingsLead(Icons.Outlined.Palette, "Theme", "Follow the phone or choose a fixed appearance")
                Row(Modifier.fillMaxWidth().selectableGroup(), horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    ThemeChoice(PennyThemeMode.SYSTEM, "System", Icons.Outlined.PhoneAndroid, themeMode, onThemeMode, Modifier.weight(1f))
                    ThemeChoice(PennyThemeMode.LIGHT, "Light", Icons.Outlined.LightMode, themeMode, onThemeMode, Modifier.weight(1f))
                    ThemeChoice(PennyThemeMode.DARK, "Dark", Icons.Outlined.DarkMode, themeMode, onThemeMode, Modifier.weight(1f))
                }
            }
        }
        item {
            SettingsSection("Notifications") {
                SettingsSwitch(Icons.Outlined.NotificationsNone, "Expense reminders", if (!notificationGranted) "Blocked by Android settings" else "Prompt me to name new debits", notificationsEnabled && notificationGranted) {
                    if (!notificationGranted) onRequestPermissions() else onNotifications(it)
                }
                SettingsDivider()
                SettingsSwitch(Icons.Outlined.MusicNote, "Penny chime", "Play Penny’s two-note reminder", notificationSoundEnabled, onNotificationSound)
                Spacer(Modifier.height(8.dp))
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp)) {
                    OutlinedButton(onClick = onTestNotification, enabled = notificationGranted && notificationsEnabled, modifier = Modifier.weight(1f)) { Text("Test notification") }
                    TextButton(onClick = {
                        context.startActivity(Intent(AndroidSettings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(AndroidSettings.EXTRA_APP_PACKAGE, context.packageName))
                    }) { Text("Android settings") }
                }
            }
        }
        item {
            SettingsSection("Access") {
                SettingsStatus(Icons.Outlined.Sms, "SMS access", if (smsGranted) "On · new bank alerts can be captured" else "Off · Penny cannot capture alerts", if (smsGranted) null else "Enable", onRequestPermissions)
            }
        }
        item {
            SettingsSection("Penny") {
                SettingsLink(Icons.Outlined.PrivacyTip, "Privacy", "Local storage, permissions, and data", onPrivacy)
                SettingsDivider()
                SettingsLink(Icons.Outlined.Info, "About", "Version, capabilities, and limits", onAbout)
            }
        }
        if (BuildConfig.DEBUG) item {
            SettingsSection("Developer tools") {
                OutlinedButton(onClick = onSimulateDebit, modifier = Modifier.fillMaxWidth()) { Text("Simulate ₹250 debit") }
                Spacer(Modifier.height(8.dp))
                OutlinedButton(onClick = onSimulateCredit, modifier = Modifier.fillMaxWidth()) { Text("Simulate ₹5,000 credit") }
            }
        }
        item {
            TextButton(
                onClick = { confirmDelete = true },
                colors = ButtonDefaults.textButtonColors(contentColor = MaterialTheme.colorScheme.error),
                modifier = Modifier.fillMaxWidth(),
            ) {
                Icon(Icons.Outlined.DeleteOutline, null)
                Spacer(Modifier.width(8.dp))
                Text("Delete all Penny data")
            }
        }
    }
    if (confirmDelete) AlertDialog(
        onDismissRequest = { confirmDelete = false },
        icon = { Icon(Icons.Outlined.DeleteOutline, null) },
        title = { Text("Delete all Penny data?") },
        text = { Text("This removes every transaction, title, draft, and setting from this phone. This cannot be undone.") },
        confirmButton = { TextButton(onClick = { onDelete(); confirmDelete = false }) { Text("Delete", color = MaterialTheme.colorScheme.error) } },
        dismissButton = { TextButton(onClick = { confirmDelete = false }) { Text("Cancel") } },
    )
}

@Composable
private fun ThemeChoice(mode: PennyThemeMode, label: String, icon: ImageVector, selected: PennyThemeMode, onSelect: (PennyThemeMode) -> Unit, modifier: Modifier) {
    val active = mode == selected
    Surface(
        modifier = modifier.heightIn(min = 76.dp).selectable(
            selected = active,
            onClick = { onSelect(mode) },
            role = Role.RadioButton,
        ),
        shape = RoundedCornerShape(18.dp),
        color = if (active) MaterialTheme.colorScheme.primaryContainer else MaterialTheme.colorScheme.surfaceVariant.copy(alpha = .55f),
    ) {
        Column(Modifier.padding(12.dp), horizontalAlignment = Alignment.CenterHorizontally, verticalArrangement = Arrangement.spacedBy(6.dp)) {
            Icon(icon, null, tint = if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant)
            Text(label, style = MaterialTheme.typography.labelMedium, color = if (active) MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant)
        }
    }
}

